"use client";
import Image from "next/image";
import { useState, Fragment } from "react";
import type { FormEvent } from "react";

type MatchRow = {
  matchId: string;
  queueId?: number;
  gameStart?: number; // epoch millis
  durationSeconds?: number;
};

const QUEUE_NAMES: Record<number, string> = {
  420: "Ranked Solo/Duo",
  440: "Ranked Flex",
  400: "Normal Draft",
  430: "Normal Blind",
  450: "ARAM",
  700: "Clash",
  900: "URF",
  1020: "One for All",
  830: "Co-op vs AI (Intro)",
  840: "Co-op vs AI (Beginner)",
  850: "Co-op vs AI (Intermediate)",
  1700: "Arena",
};

const MAP_NAMES: Record<number, string> = {
  11: "Summoner's Rift",
  12: "Howling Abyss",
  21: "Nexus Blitz",
};

type ParticipantRow = {
  key: string;
  summonerName?: string;
  championName?: string;
  kills?: number;
  deaths?: number;
  assists?: number;
  win?: boolean;
};

function Participants({ rawInfo }: { rawInfo: Record<string, unknown> }) {
  const participantsUnknown = (rawInfo as { participants?: unknown })
    .participants;
  const list = Array.isArray(participantsUnknown) ? participantsUnknown : [];
  const rows = list.map((p) => {
    const obj = (p ?? {}) as Record<string, unknown>;
    const summonerName =
      typeof obj.summonerName === "string" ? obj.summonerName : undefined;
    const championName =
      typeof obj.championName === "string" ? obj.championName : undefined;
    const kills = typeof obj.kills === "number" ? obj.kills : undefined;
    const deaths = typeof obj.deaths === "number" ? obj.deaths : undefined;
    const assists = typeof obj.assists === "number" ? obj.assists : undefined;
    const win = typeof obj.win === "boolean" ? obj.win : undefined;
    const puuid = typeof obj.puuid === "string" ? obj.puuid : undefined;
    return {
      key: puuid ?? `${championName}-${summonerName}`,
      summonerName,
      championName,
      kills,
      deaths,
      assists,
      win,
    };
  });

  if (rows.length === 0) {
    return (
      <p className="text-xs text-foreground/60">
        No participant data available.
      </p>
    );
  }

  return (
    <div className="overflow-x-auto border border-black/10 dark:border-white/10 rounded-md">
      <table className="min-w-full text-xs sm:text-sm">
        <thead className="bg-black/5 dark:bg-white/5 text-left">
          <tr>
            <th className="px-3 py-2">Summoner</th>
            <th className="px-3 py-2">Champion</th>
            <th className="px-3 py-2">K / D / A</th>
            <th className="px-3 py-2">Result</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r: ParticipantRow) => (
            <tr
              key={r.key}
              className="border-t border-black/5 dark:border-white/10"
            >
              <td className="px-3 py-2">{r.summonerName ?? "-"}</td>
              <td className="px-3 py-2">{r.championName ?? "-"}</td>
              <td className="px-3 py-2">
                {[r.kills ?? "-", r.deaths ?? "-", r.assists ?? "-"].join(
                  " / "
                )}
              </td>
              <td className="px-3 py-2">
                {typeof r.win === "boolean" ? (r.win ? "Win" : "Loss") : "-"}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function Home() {
  const [gameName, setGameName] = useState("");
  const [tagLine, setTagLine] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [matches, setMatches] = useState<MatchRow[]>([]);
  const [rawById, setRawById] = useState<Record<string, unknown>>({});
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const handleSearch = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    setMatches([]);
    try {
      const params = new URLSearchParams({ gameName, tagLine });
      const res = await fetch(`/api/matches?${params.toString()}`);
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        throw new Error(data?.error || `Request failed: ${res.status}`);
      }
      if (Array.isArray(data?.matches)) {
        const byId: Record<string, unknown> = {};
        const rows: MatchRow[] = data.matches
          .map((m: unknown) => {
            const obj = m as Record<string, unknown>;
            const metadata = (obj?.metadata ?? {}) as Record<string, unknown>;
            const info = (obj?.info ?? {}) as Record<string, unknown>;
            const matchId = String(metadata?.matchId ?? "");
            const queueId =
              typeof info?.queueId === "number" ? info.queueId : undefined;
            const gameStart =
              typeof info?.gameStartTimestamp === "number"
                ? info.gameStartTimestamp
                : typeof info?.gameCreation === "number"
                ? info.gameCreation
                : undefined;
            const durationSeconds =
              typeof info?.gameDuration === "number"
                ? info.gameDuration
                : undefined;
            if (matchId) byId[matchId] = obj;
            return { matchId, queueId, gameStart, durationSeconds };
          })
          .filter((r: MatchRow) => r.matchId);
        setMatches(rows);
        setRawById(byId);
        setExpandedId(null);
      } else {
        setMatches([]);
        setRawById({});
        setExpandedId(null);
      }
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Something went wrong";
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="font-sans grid grid-rows-[20px_1fr_20px] items-center justify-items-center min-h-screen p-8 pb-20 gap-16 sm:p-20">
      <main className="flex flex-col gap-[32px] row-start-2 items-center sm:items-start">
        <Image
          className="dark:invert"
          src="/next.svg"
          alt="Next.js logo"
          width={180}
          height={38}
          priority
        />
        <ol className="font-mono list-inside list-decimal text-sm/6 text-center sm:text-left">
          <li className="mb-2 tracking-[-.01em]">
            Get started by editing{" "}
            <code className="bg-black/[.05] dark:bg-white/[.06] font-mono font-semibold px-1 py-0.5 rounded">
              src/app/page.tsx
            </code>
            .
          </li>
          <li className="tracking-[-.01em]">
            Save and see your changes instantly.
          </li>
        </ol>

        <div className="w-full max-w-xl flex flex-col gap-3">
          <form
            onSubmit={handleSearch}
            className="flex flex-col sm:flex-row gap-3 w-full"
          >
            <input
              type="text"
              value={gameName}
              onChange={(e) => setGameName(e.target.value)}
              placeholder="Game Name (e.g. SomePlayer)"
              className="flex-1 rounded-md border border-black/10 dark:border-white/20 bg-transparent px-3 py-2"
              aria-label="Game Name"
            />
            <input
              type="text"
              value={tagLine}
              onChange={(e) => setTagLine(e.target.value)}
              placeholder="Tag Line (e.g. NA1)"
              className="w-full sm:w-40 rounded-md border border-black/10 dark:border-white/20 bg-transparent px-3 py-2"
              aria-label="Tag Line"
            />
            <button
              type="submit"
              disabled={loading || !gameName || !tagLine}
              className="rounded-md border border-solid border-transparent transition-colors flex items-center justify-center bg-foreground text-background font-medium text-sm sm:text-base h-10 sm:h-12 px-4 sm:px-5 disabled:opacity-50"
            >
              {loading ? "Searching…" : "Search matches"}
            </button>
          </form>
          {error && (
            <p className="text-red-600 text-sm" role="alert">
              {error}
            </p>
          )}
          <p className="text-sm text-foreground/70">
            Found {matches.length} match{matches.length === 1 ? "" : "es"}.
          </p>
          {matches.length > 0 && (
            <div className="overflow-x-auto border border-black/10 dark:border-white/10 rounded-md">
              <table className="min-w-full text-sm">
                <thead className="bg-black/5 dark:bg-white/5 text-left">
                  <tr>
                    <th className="px-3 py-2">Match</th>
                    <th className="px-3 py-2">Queue</th>
                    <th className="px-3 py-2">Start</th>
                    <th className="px-3 py-2">Duration</th>
                  </tr>
                </thead>
                <tbody>
                  {matches.map((m) => {
                    const start =
                      typeof m.gameStart === "number"
                        ? new Date(m.gameStart).toLocaleString()
                        : "-";
                    const dur =
                      typeof m.durationSeconds === "number"
                        ? `${Math.floor(m.durationSeconds / 60)}m ${Math.floor(
                            m.durationSeconds % 60
                          )}s`
                        : "-";
                    const queueLabel =
                      typeof m.queueId === "number"
                        ? `${QUEUE_NAMES[m.queueId] ?? "Unknown"} (${
                            m.queueId
                          })`
                        : "-";

                    const isExpanded = expandedId === m.matchId;
                    const raw = rawById[m.matchId] as
                      | Record<string, unknown>
                      | undefined;
                    const info = (raw?.info ?? {}) as Record<string, unknown>;
                    const mapId =
                      typeof info?.mapId === "number" ? info.mapId : undefined;
                    const mapName =
                      typeof mapId === "number"
                        ? MAP_NAMES[mapId] ?? `Map ${mapId}`
                        : "-";
                    const gameMode =
                      typeof info?.gameMode === "string"
                        ? (info.gameMode as string)
                        : "-";

                    return (
                      <Fragment key={m.matchId}>
                        <tr className="border-t border-black/5 dark:border-white/10">
                          <td className="px-3 py-2">
                            <button
                              type="button"
                              onClick={() =>
                                setExpandedId(isExpanded ? null : m.matchId)
                              }
                              className="font-mono text-xs sm:text-sm break-all hover:underline"
                              aria-expanded={isExpanded}
                              aria-controls={`match-${m.matchId}`}
                            >
                              {isExpanded ? "▾" : "▸"} {m.matchId}
                            </button>
                          </td>
                          <td className="px-3 py-2">{queueLabel}</td>
                          <td className="px-3 py-2">{start}</td>
                          <td className="px-3 py-2">{dur}</td>
                        </tr>
                        {isExpanded && (
                          <tr className="border-t border-black/5 dark:border-white/10 bg-black/[.025] dark:bg-white/[.03]">
                            <td
                              colSpan={4}
                              id={`match-${m.matchId}`}
                              className="px-3 py-3"
                            >
                              <div className="flex flex-col gap-2">
                                <div className="text-xs text-foreground/80">
                                  <span className="mr-4">
                                    <strong>Mode:</strong> {gameMode}
                                  </span>
                                  <span>
                                    <strong>Map:</strong> {mapName}
                                  </span>
                                </div>
                                {/* Participants */}
                                <Participants rawInfo={info} />
                              </div>
                            </td>
                          </tr>
                        )}
                      </Fragment>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>
      <footer className="row-start-3 flex gap-[24px] flex-wrap items-center justify-center"></footer>
    </div>
  );
}
